# SPDX-License-Identifier: Apache-2.0
#
# Linker version script for libv8malloc.so. A single SONAME-aligned
# version node holds every exported symbol; new symbols are added to
# the same node within a major release. A new node (V8MALLOC_2.0, etc.)
# is introduced only on a major bump.

V8MALLOC_1.0 {
	global:
		v8m_version;
		v8m_version_major;
		v8m_version_minor;
		v8m_version_patch;

		v8m_malloc;
		v8m_free;
		v8m_calloc;
		v8m_realloc;
		v8m_reallocarray;
		v8m_malloc_usable_size;
		v8m_aligned_alloc;
		v8m_posix_memalign;
		v8m_memalign;
		v8m_valloc;
		v8m_pvalloc;
		v8m_set_option;
		v8m_get_option;
		v8m_get_stats;
		v8m_dump_stats;
		v8m_set_oom_handler;
		v8m_set_soft_limit;
		v8m_get_soft_limit;
		v8m_is_valid_ptr;
		v8m_ptr_info;

		malloc;
		free;
		calloc;
		realloc;
		reallocarray;
		malloc_usable_size;
		aligned_alloc;
		posix_memalign;
		memalign;
		valloc;
		pvalloc;

		mallinfo;
		mallinfo2;
		mallopt;
		malloc_stats;
		malloc_info;
		malloc_trim;

		__libc_malloc;
		__libc_free;
		__libc_calloc;
		__libc_realloc;
		__libc_memalign;
		__libc_valloc;
		__libc_pvalloc;
	local:
		*;
};
